function SectionHead({eyebrow,title,text}:{eyebrow:string;title:string;text:string}) { return <header className="section-head"><span>{eyebrow}</span><h2>{title}</h2><p>{text}</p></header> }
function StatusIcon({status}:{status:string}) { const Icon=status==="completed"?ReceiptText:status==="ready"?Bell:status==="served"?UtensilsCrossed:ChefHat; return <Icon size={15}/> }
function statusLabel(status:string) { return ({kitchen:"Sent to kitchen",cooking:"Cooking",ready:"Ready to serve",served:"Awaiting payment",completed:"Paid"} as Record<string,string>)[status]||status; }
